ckground:var(--atom-card,#fff)}.catalog{display:grid;grid-template-columns:1fr 1fr;gap:9px}.work{display:flex;flex-direction:column;align-items:flex-start;text-align:left;min-height:137px;background:var(--atom-card,#fff);color:inherit;border-radius:17px;padding:13px}.work h2{font-size:16px;margin:7px 0 4px}.work p{font-size:12px;line-height:1.4;color:var(--atom-secondary-text,#65656d);margin:0}.work small{margin-top:auto;padding-top:8px}.mark{width:36px;height:36px;border-radius:10px;background:var(--atom-paper,#f2f2f7);display:grid;place-items:center;color:var(--atom-accent,#007aff);font-size:21px}.search{display:flex;gap:6px}.search input{flex:1;min-width:0}.search button{white-space:nowrap}.pre{font:11px/1.5 ui-monospace,SFMono-Regular,monospace;white-space:pre-wrap;overflow-wrap:anywhere;margin:8px 0;user-select:text}.detail-meta{display:flex;gap:6px;flex-wrap:wrap}.pill{font-size:11px;padding:4px 7px;background:var(--atom-paper,#f2f2f7);border-radius:7px}.list-button{display:block;width:100%;text-align:left;background:var(--atom-card,#fff);color:inherit;margin-bottom:7px}.empty{text-align:center;padding:20px 10px}.label{font-size:11px;color:var(--atom-secondary-text,#65656d)}a{color:var(--atom-accent,#007aff)}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
