body[data-atom-app=market] .catalog .work h2{font-size:17px;line-height:1.3;align-self:auto;margin:0!important}body[data-atom-app=market] .catalog .work p{font-size:10px;-webkit-line-clamp:1;opacity:.86}body[data-atom-app=market] .catalog .work small{font-size:9px;opacity:.7;margin:0;padding-top:2px}
