alse;notice=(r.app?.name||detail?.work?.title||'应用')+' 已恢复所选资源；应用数据未回退。';installState=await api('install-state',{version_id:version});release=installState.history?.[0]?.release_id||'';}if(a==='fork'){if(!account.authenticated){view='account';notice='先登录，再衍生为自己的私有草稿。';return;}await api('fork',{version_id:version});drafts=(await api('drafts')).drafts||[];view='drafts';notice='已创建私有草稿，请在电脑工作台继续。';}});});
